/* activity-icon/index.css */
.mds-activity-icon {
  align-items: center;
  /*
   * content-box so block-size/inline-size declare the ICON content area.
   * Padding then expands the tile beyond that — matching Figma's structure
   * where "size" is the icon and padding is added by the container variant.
   */
  box-sizing: content-box;
  display: inline-flex;
  flex-shrink: 0;
  justify-content: center;
  overflow: hidden;
}

/* none: no background tile, no padding — tile equals the icon size */
.mds-activity-icon--none {
  border-radius: var(--mds-border-radius-none);
}

/*
 * default: 8px padding each side — tile = icon + 16px (e.g. lg: 24+16 = 40px total).
 * large:  12px padding each side — tile = icon + 24px (e.g. lg: 24+24 = 48px total).
 */
.mds-activity-icon--default {
  border-radius: var(--mds-border-radius-xl);
  padding: var(--mds-spacing-xs);
}

.mds-activity-icon--large {
  border-radius: var(--mds-border-radius-xl);
  padding: var(--mds-spacing-sm);
}

/* Figma uses a smaller outer radius for default+sm only. */
.mds-activity-icon--default.mds-activity-icon--size-sm {
  border-radius: var(--mds-border-radius-lg);
}

/* Category background colors apply only when a background container is active. */
.mds-activity-icon--default.mds-activity-icon--category-assessment,
.mds-activity-icon--large.mds-activity-icon--category-assessment {
  background-color: var(--mds-activity-icon-assessment-bg);
}

.mds-activity-icon--default.mds-activity-icon--category-collaboration,
.mds-activity-icon--large.mds-activity-icon--category-collaboration {
  background-color: var(--mds-activity-icon-collaboration-bg);
}

.mds-activity-icon--default.mds-activity-icon--category-communication,
.mds-activity-icon--large.mds-activity-icon--category-communication {
  background-color: var(--mds-activity-icon-communication-bg);
}

.mds-activity-icon--default.mds-activity-icon--category-interactive,
.mds-activity-icon--large.mds-activity-icon--category-interactive {
  background-color: var(--mds-activity-icon-interactive-bg);
}

.mds-activity-icon--default.mds-activity-icon--category-other,
.mds-activity-icon--large.mds-activity-icon--category-other {
  background-color: var(--mds-activity-icon-other-bg);
}

.mds-activity-icon--default.mds-activity-icon--category-resource,
.mds-activity-icon--large.mds-activity-icon--category-resource {
  background-color: var(--mds-activity-icon-resource-bg);
}

/* Size variants */
.mds-activity-icon--size-sm {
  block-size: var(--mds-icons-sm);
  inline-size: var(--mds-icons-sm);
}

.mds-activity-icon--size-md {
  /* Intentionally follows the Figma token mapping, where md uses the lg icon token. */
  block-size: var(--mds-icons-lg);
  inline-size: var(--mds-icons-lg);
}

.mds-activity-icon--size-lg {
  /* Intentionally follows the Figma token mapping, where lg uses the xl icon token. */
  block-size: var(--mds-icons-xl);
  inline-size: var(--mds-icons-xl);
}

.mds-activity-icon--size-xl {
  /* Intentionally follows the Figma token mapping, where xl uses the xxl icon token. */
  block-size: var(--mds-icons-xxl);
  inline-size: var(--mds-icons-xxl);
}

.mds-activity-icon__asset {
  block-size: 100%;
  border-radius: var(--mds-border-radius-xs);
  display: block;
  inline-size: 100%;
}

/* breadcrumb/index.css */
/* ─── List ─────────────────────────────────────────────────────────────────── */
.mds-breadcrumb__list.breadcrumb {
  /* Never wrap to a second line — labels truncate via flex shrink so the
     trail always fits inline. */
  flex-wrap: nowrap;
  align-items: center;
  margin-bottom: 0;
  padding: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ─── Items ─────────────────────────────────────────────────────────────────── */
.breadcrumb-item.items-2 {
  max-width: 50%;
}

.breadcrumb-item.items-3 {
  max-width: 33.3333%;
}

.breadcrumb-item.items-4 {
  max-width: 25%;
}

.breadcrumb-item.mds-breadcrumb__item--current {
  max-width: 50%;
}

.breadcrumb-item {
  /* Each item is its own flex row: the Bootstrap ::before divider and the
     link/span become flex siblings rather than inline boxes. This eliminates
     the inline-box strut that previously added 2 px to every link item
     (making them 26 px while the current-page item was 24 px), and prevents
     the ::before + span from wrapping to a second line when the <li> is
     narrower than the span's natural width. Bootstrap's float:left on
     ::before is ignored inside a flex container - the divider becomes a
     zero-shrink flex item at its natural content size, which is correct. */
  display: flex;
  align-items: center;
  flex: 0 1 auto;
  min-width: 0;
}

/* --- Link items --------------------------------------------------------------------------- */
/* When a Tooltip wraps a Link it becomes a flex item inside the <li> flex
   container. Its default min-width:auto prevents the flex algorithm from
   shrinking the wrapper, causing text overlap on narrow viewports. Overriding
   to min-width:0 lets the wrapper shrink freely alongside the other items. */
.breadcrumb-item .mds-tooltip {
  min-width: 0;
}

/* The overflow trigger is wrapped by Dropdown's root element (.mds-dropdown,
   display:inline-flex) so it can reuse Dropdown's floating-ui orchestration.
   display:contents makes that wrapper transparent to the <li> flex layout,
   matching the un-wrapped button that used to be the direct flex item. */
.mds-breadcrumb__item--overflow .mds-dropdown {
  display: contents;
}

/* ─── Shared text styles ─────────────────────────────────────────────────────── */
/* The overflow trigger button and current-page label are not rendered by the
   Link component, so they need explicit typography to match it. Token values
   mirror those set in link.css so the row stays visually uniform. */
.mds-breadcrumb__overflow-trigger,
.mds-breadcrumb__item--current .mds-breadcrumb__label {
  font-family: var(--mds-font-family-base);
  font-size: var(--mds-font-size-paragraph-default);
  /* paragraph-xs matches the Link component's own line-height token */
  line-height: var(--mds-line-height-paragraph-xs);
  letter-spacing: var(--mds-letter-spacing-default);
}

/* ─── Link truncation overrides (on top of the Link component styles) ────────── */
/* Link is inline-flex so min-width:0 is required to allow it to shrink below
   its natural content width when the breadcrumb row is too narrow. */
.mds-breadcrumb__link.mds-link {
  min-width: 0;
}

/* Truncate the text inside Link's inner label span. min-width:0 lets the flex
   item shrink below its natural text width (flex default is min-width:auto). */
.mds-breadcrumb__link.mds-link .mds-link__label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
  line-height: var(--mds-line-height-paragraph-default);
}

/* ─── Current page label ─────────────────────────────────────────────────────── */
.mds-breadcrumb__item--current .mds-breadcrumb__label {
  color: var(--mds-text-subtle);
  font-weight: var(--mds-typography-font-weight-regular);
  line-height: var(--mds-line-height-paragraph-default);
  /* The span is a flex item inside the current-page <li> flex container.
     Flex items are blockified, so overflow:hidden + text-overflow:ellipsis
     work without an explicit display override. flex:1 1 auto fills the
     remaining space after the ::before divider; min-width:0 allows the span
     to shrink below its natural text width when the container is narrow. */
  flex: 1 1 auto;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* The label is focusable (tabIndex=0) so its truncation tooltip is reachable
   by keyboard, matching the Link items' focus-visible treatment. */
.mds-breadcrumb__item--current .mds-breadcrumb__label:focus {
  outline: none;
}

.mds-breadcrumb__item--current .mds-breadcrumb__label:focus-visible {
  outline: none;
  box-shadow: inset 0 calc(-1 * var(--mds-stroke-weight-md)) 0 var(--mds-focus-default);
}

/* ─── Overflow trigger ───────────────────────────────────────────────────────── */
/* The overflow button is visually styled to match the Link component. */
.mds-breadcrumb__overflow-trigger {
  display: inline-flex;
  align-items: center;
  line-height: var(--mds-line-height-paragraph-default);
  padding: 0;
  background: none;
  border: none;
  cursor: pointer;
  /* Colour and weight to match Link's primary resting state */
  color: var(--mds-text-link-primary-default);
  font-weight: var(--mds-font-weight-regular);
  text-decoration: none;
}

.mds-breadcrumb__overflow-trigger:hover:not(:focus-visible) {
  color: var(--mds-text-link-primary-hover);
  text-decoration: underline;
  text-decoration-thickness: from-font;
  text-underline-position: from-font;
}

.mds-breadcrumb__overflow-trigger:active {
  color: var(--mds-text-link-primary-hover);
}

.mds-breadcrumb__overflow-trigger:focus {
  outline: none;
}

.mds-breadcrumb__overflow-trigger:focus-visible {
  /* Use an inset underline so focus does not change layout height. */
  outline: none;
  box-shadow: inset 0 calc(-1 * var(--mds-stroke-weight-md)) 0 var(--mds-focus-default);
}

/* Link's base focus style adds border/padding and can shift breadcrumb rows.
   Override to a non-layout-affecting inset underline within breadcrumb only. */
.mds-breadcrumb__link.mds-link:focus-visible {
  padding-bottom: 0;
  border-bottom: 0;
  box-shadow: inset 0 calc(-1 * var(--mds-stroke-weight-md)) 0 var(--mds-focus-default);
}

/* ─── Overflow link items (per-element overrides) ────────────────────────────── */
/* Bootstrap's breadcrumb divider is CSS-generated via content: and is therefore
   read aloud by screen readers (VoiceOver, NVDA, JAWS). Override it here with
   the CSS content alt-text syntax (content: <value> / "") to keep the visual
   separator while silencing it for assistive technologies (MDN: Breadcrumb
   navigation — Accessibility concerns; WCAG 1.3.3). */
.mds-breadcrumb .breadcrumb-item + .breadcrumb-item::before {
  content: "/"/"";
  color: var(--mds-text-muted);
  /* Own spacing on both sides of the divider to keep gaps visually even. */
  margin-inline: var(--mds-spacing-xs);
  padding: 0;
  float: none;
}

.mds-breadcrumb .breadcrumb-item + .breadcrumb-item {
  /* Neutralize Bootstrap's physical padding so RTL/LTR both rely on the
     symmetric divider margins above. */
  padding-inline: 0;
}

/* avatar/index.css */
/*
 * avatar.css
 * Styles for the Avatar component.
 *
 * Sizing uses --mds-scale-* primitives because no semantic avatar-size tokens
 * exist in the current token set. When dedicated tokens are added, replace
 * the scale references here.
 */
.mds-avatar {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: var(--mds-border-radius-pill);
  background-color: var(--mds-bg-surface-strong);
  color: var(--mds-text-default);
  /* Prevent the avatar from collapsing in flex or grid containers */
  flex-shrink: 0;
}

/* ── Size variants ─────────────────────────────────────────────────────────── */
.mds-avatar--xs {
  width: var(--mds-avatars-xs);
  height: var(--mds-avatars-xs);
}

.mds-avatar--sm {
  width: var(--mds-avatars-sm);
  height: var(--mds-avatars-sm);
}

.mds-avatar--md {
  width: var(--mds-avatars-md);
  height: var(--mds-avatars-md);
}

.mds-avatar--lg {
  width: var(--mds-avatars-lg);
  height: var(--mds-avatars-lg);
}

.mds-avatar--xl {
  width: var(--mds-avatars-xl);
  height: var(--mds-avatars-xl);
}

.mds-avatar--xxl {
  width: var(--mds-avatars-xxl);
  height: var(--mds-avatars-xxl);
}

/* ── Image content ─────────────────────────────────────────────────────────── */
.mds-avatar__image {
  /* Absolutely positioned so it overlays the initials base layer.
     overflow: hidden on the parent clips it to the circular shape. */
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* ── Initials content ──────────────────────────────────────────────────────── */
.mds-avatar__initials {
  font-family: var(--mds-font-family-base);
  letter-spacing: var(--mds-letter-spacing-default);
  /* line-height is intentionally the unitless value 1, not a token.
     All --mds-line-height-* tokens are absolute rem values designed for prose
     (e.g. --mds-line-height-paragraph-lead resolves to 2.5rem). Using any of
     them here would add a fixed vertical gutter that is independent of the
     avatar's font-size, causing the glyphs to sit off-centre in the flex
     container at one or more size variants. The unitless 1 means "line box
     height = 1× font-size" and scales correctly with every size variant. */
  line-height: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  user-select: none;
}

/* xs and sm are image-only per the design spec. Hide the initials layer at
   these sizes so a blank circle is not displayed if the DOM node is present
   (e.g. during an image-load error before imgFailed state flips). */
.mds-avatar--xs .mds-avatar__initials,
.mds-avatar--sm .mds-avatar__initials {
  display: none;
}

/* When an image is visible the initials layer is both aria-hidden and
   visually hidden. Using visibility: hidden (rather than opacity/display)
   means the element stays in the DOM so the fallback is instant on error,
   but removes the underlying text from axe's colour-contrast analysis. */
.mds-avatar--has-image .mds-avatar__initials {
  visibility: hidden;
}

/* md uses the smallest paragraph size. */
.mds-avatar--md .mds-avatar__initials {
  font-size: var(--mds-font-size-paragraph-small);
  font-weight: var(--mds-font-weight-medium);
}

.mds-avatar--lg .mds-avatar__initials {
  font-size: var(--mds-font-size-paragraph-default);
  font-weight: var(--mds-font-weight-regular);
}

.mds-avatar--xl .mds-avatar__initials,
.mds-avatar--xxl .mds-avatar__initials {
  font-size: var(--mds-font-size-paragraph-lead);
  font-weight: var(--mds-font-weight-regular);
}

/* badge/index.css */
.mds-badge {
  display: inline-flex;
  align-items: center;
  gap: 0;
  padding: var(--mds-spacing-xxs) var(--mds-spacing-xs);
  border-radius: var(--mds-border-radius-sm);
  font-family: var(--mds-font-family-base);
  font-weight: var(--mds-font-weight-medium);
  font-size: var(--mds-font-size-paragraph-small);
  line-height: var(--mds-line-height-paragraph-xs);
  letter-spacing: var(--mds-letter-spacing-default);
  white-space: nowrap;
  vertical-align: baseline;
}

.mds-badge--has-icon {
  gap: var(--mds-spacing-xxs);
}

/* Normalize icon dimensions to match the badge icon token across <i> and <svg> usage. */
.mds-badge > i,
.mds-badge > svg {
  width: var(--mds-icons-xxs);
  height: var(--mds-icons-xxs);
  font-size: var(--mds-icons-xxs);
  flex-shrink: 0;
}

/* Pill shape overrides the default rounded corners */
.mds-badge--pill {
  border-radius: var(--mds-border-radius-pill);
}

/*
 * Per-variant colour rules.
 * Default contrast: solid coloured background with inverse text.
 * Subtle contrast (.mds-badge--subtle): light tinted background, dark feedback text, visible border.
 */
.mds-badge--subtle {
  border: var(--mds-stroke-weight-sm) solid transparent;
}

/* --- Primary --- */
.mds-badge--primary {
  background-color: var(--mds-bg-feedback-primary-default);
  color: var(--mds-text-inverse);
}

.mds-badge--primary.mds-badge--subtle {
  background-color: var(--mds-bg-feedback-primary-subtle);
  color: var(--mds-text-feedback-primary);
  border-color: var(--mds-border-feedback-primary);
}

/* --- Secondary --- */
.mds-badge--secondary {
  background-color: var(--mds-bg-feedback-secondary-default);
  color: var(--mds-text-feedback-secondary);
}

.mds-badge--secondary.mds-badge--subtle {
  background-color: var(--mds-bg-feedback-secondary-subtle);
