  -webkit-mask-size: var(--mds-icons-md) var(--mds-icons-md);
}

.mds-close-button.btn-close.mds-close-button--lg {
  inline-size: var(--mds-icons-lg);
  block-size: var(--mds-icons-lg);
  mask-size: var(--mds-icons-lg) var(--mds-icons-lg);
  -webkit-mask-size: var(--mds-icons-lg) var(--mds-icons-lg);
