.mds-dropdown-trigger__chevron--sm {
  inline-size: var(--mds-icons-xxs);
  mask-image: url("data:image/svg+xml,%3Csvg%20width%3D%228%22%20height%3D%228%22%20viewBox%3D%220%200%208%208%22%20fill%3D%22none%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%20%3Cpath%20d%3D%22M3.64844%205.85156L0.648438%202.85156C0.445312%202.66406%200.445312%202.33594%200.648438%202.14844C0.835938%201.94531%201.16406%201.94531%201.35156%202.14844L4.00781%204.78906L6.64844%202.14844C6.83594%201.94531%207.16406%201.94531%207.35156%202.14844C7.55469%202.33594%207.55469%202.66406%207.35156%202.85156L4.35156%205.85156C4.16406%206.05469%203.83594%206.05469%203.64844%205.85156Z%22%20fill%3D%22%231D2125%22%2F%3E%20%3C%2Fsvg%3E");
  -webkit-mask-image: url("data:image/svg+xml,%3Csvg%20width%3D%228%22%20height%3D%228%22%20viewBox%3D%220%200%208%208%22%20fill%3D%22none%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%20%3Cpath%20d%3D%22M3.64844%205.85156L0.648438%202.85156C0.445312%202.66406%200.445312%202.33594%200.648438%202.14844C0.835938%201.94531%201.16406%201.94531%201.35156%202.14844L4.00781%204.78906L6.64844%202.14844C6.83594%201.94531%207.16406%201.94531%207.35156%202.14844C7.55469%202.33594%207.55469%202.66406%207.35156%202.85156L4.35156%205.85156C4.16406%206.05469%203.83594%206.05469%203.64844%205.85156Z%22%20fill%3D%22%231D2125%22%2F%3E%20%3C%2Fsvg%3E");
