/* Open (Figma State=active): filled appearances keep the active fill and gain
   a 1px inside ring. The inset box-shadow is a pressed-state ring, not a
   focus ring — focus rings remain outline-based per the focus ring pattern. */
.mds-dropdown-trigger--open.mds-btn.btn.btn-secondary,
.mds-dropdown-trigger--open.mds-btn.btn.btn-ghost {
  background-color: var(--mds-bg-interactive-secondary-active);
  color: var(--mds-text-subtle);
  box-shadow: inset 0 0 0 var(--mds-stroke-weight-sm) var(--mds-border-interactive-secondary-active);
}

/* Open outlined appearance: solid dark fill with inverse text. */
.mds-dropdown-trigger--open.mds-btn.btn.btn-outline-secondary {
  border-color: var(--mds-border-interactive-secondary-active);
  background-color: var(--mds-border-interactive-secondary-active);
  color: var(--mds-text-inverse);
}

/* nav-pill trigger renders a <button>; nav-pill.css already resets border and
   background for the class, so only layout inherited from Bootstrap's button
   normalisation needs neutralising. */
.mds-dropdown-trigger--nav-pill {
  font-family: var(--mds-font-family-base);
}

.mds-dropdown-trigger--open.mds-nav-pill {
  background-color: var(--mds-bg-nav-pill-pressed);
}

/* ------------------------------------------------------------------ */
/* Menu panel                                                          */
/* ------------------------------------------------------------------ */
.mds-dropdown-menu {
  display: flex;
  flex-direction: column;
  gap: var(--mds-spacing-xxs);
  align-items: stretch;
  min-inline-size: 13.5625rem; /* 217px per Figma; grows with content */
  padding: var(--mds-spacing-xxs);
  background-color: var(--mds-bg-surface-default);
  border: var(--mds-stroke-weight-sm) solid var(--mds-border-default);
  border-radius: var(--mds-border-radius-md);
  overflow: clip;
}

/* ------------------------------------------------------------------ */
/* Item rows — shared chrome                                           */
/* ------------------------------------------------------------------ */
.mds-dropdown-item {
  display: flex;
  gap: var(--mds-spacing-xs);
  align-items: center;
  inline-size: 100%;
  padding: var(--mds-spacing-xs) var(--mds-spacing-sm);
  border: none;
  border-radius: var(--mds-border-radius-xs);
  background: none;
  margin: 0;
  text-align: start;
  cursor: pointer;
  font-family: var(--mds-font-family-base);
  color: var(--mds-text-subtle);
  position: relative;
  box-sizing: border-box;
}

.mds-dropdown-item:disabled,
.mds-dropdown-item[aria-disabled=true] {
  cursor: default;
  pointer-events: none;
  color: var(--mds-text-muted);
}

/* Rows with a description top-align their content. */
.mds-dropdown-item--with-description {
  align-items: flex-start;
}

.mds-dropdown-item:focus {
  box-shadow: none;
  outline: none;
}

.mds-dropdown-item:focus-visible {
  outline: var(--mds-stroke-weight-md) solid var(--mds-focus-default);
  outline-offset: var(--mds-spacing-offset);
  box-shadow: none;
}

.mds-dropdown-item__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  block-size: 24px; /* 24px per Figma. */
  flex-shrink: 0;
}

.mds-dropdown-item__icon i,
.mds-dropdown-item__icon svg {
  inline-size: var(--mds-icons-xs);
  block-size: var(--mds-icons-xs);
  font-size: var(--mds-icons-xs);
  line-height: 1;
}

.mds-dropdown-item__label-wrap {
  display: flex;
  flex: 1 0 0;
  min-inline-size: 0;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
}

.mds-dropdown-item--with-description .mds-dropdown-item__label-wrap {
  gap: var(--mds-spacing-xxs);
}

.mds-dropdown-item__label {
  font-size: var(--mds-font-size-paragraph-default);
  font-weight: var(--mds-font-weight-regular);
  line-height: var(--mds-line-height-paragraph-default);
  white-space: nowrap;
  inline-size: 100%;
  min-inline-size: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.mds-dropdown-item__description {
  font-size: var(--mds-font-size-paragraph-small);
  font-weight: var(--mds-font-weight-regular);
  line-height: var(--mds-line-height-paragraph-small);
  color: var(--mds-text-muted);
  white-space: normal;
}

/* Figma: on hover (and disabled) the description matches the row color. */
.mds-dropdown-item:hover .mds-dropdown-item__description,
.mds-dropdown-item:disabled .mds-dropdown-item__description,
.mds-dropdown-item[aria-disabled=true] .mds-dropdown-item__description {
  color: inherit;
}

/* ------------------------------------------------------------------ */
/* Action item                                                         */
/* ------------------------------------------------------------------ */
.mds-dropdown-item--action:hover:not(:disabled):not([aria-disabled=true]) {
  background-color: var(--mds-bg-interactive-primary-default-light);
}

.mds-dropdown-item--action:active:not(:disabled):not([aria-disabled=true]) {
  background-color: var(--mds-bg-interactive-primary-default-light);
}

.mds-dropdown-item--action[role=menuitem].mds-dropdown-item--danger {
  color: var(--mds-text-danger);
}

.mds-dropdown-item--action.mds-dropdown-item--danger:hover:not(:disabled):not([aria-disabled=true]) {
  color: var(--mds-text-danger);
  background-color: var(--mds-bg-interactive-danger-default-light);
}

.mds-dropdown-item--action.mds-dropdown-item--danger:active:not(:disabled):not([aria-disabled=true]) {
  background-color: var(--mds-bg-interactive-danger-default-light);
}

.mds-dropdown-item--action[role=menuitem].mds-dropdown-item--danger:disabled,
.mds-dropdown-item--action[role=menuitem].mds-dropdown-item--danger[aria-disabled=true] {
  color: var(--mds-text-danger-disabled);
}

.mds-dropdown-item--action[role=menuitem].mds-dropdown-item--danger:focus-visible {
  outline-color: var(--mds-focus-danger);
}

/* Link variant: reset default anchor styling to match button appearance */
.mds-dropdown-item--action[role=menuitem] {
  text-decoration: none;
  color: var(--mds-text-subtle);
}

.mds-dropdown-item--action[role=menuitem][aria-disabled=true] {
  color: var(--mds-text-muted);
}

.mds-dropdown-item--action[role=menuitem]:not(.mds-dropdown-item--danger):hover,
.mds-dropdown-item--action[role=menuitem]:not(.mds-dropdown-item--danger):active,
.mds-dropdown-item--action[role=menuitem]:not(.mds-dropdown-item--danger):focus,
.mds-dropdown-item--action[role=menuitem]:not(.mds-dropdown-item--danger):visited {
  text-decoration: none;
  color: var(--mds-text-subtle);
}

/* ------------------------------------------------------------------ */
/* Select item                                                         */
/* ------------------------------------------------------------------ */
.mds-dropdown-item--select:hover:not(:disabled):not([aria-disabled=true]) {
  background-color: var(--mds-bg-interactive-primary-default-light);
}

.mds-dropdown-item--select:active:not(:disabled):not([aria-disabled=true]) {
  background-color: var(--mds-bg-interactive-primary-default-light);
}

.mds-dropdown-item--select.mds-dropdown-item--selected {
  background-color: var(--mds-bg-surface-subtle);
}

/* Hover wins over the selected fill, matching the Figma state matrix. */
.mds-dropdown-item--select.mds-dropdown-item--selected:hover:not(:disabled):not([aria-disabled=true]) {
  background-color: var(--mds-bg-interactive-primary-default-light);
}

/* Check mark — Figma color/theme/primary; text-link token carries the same
  semantic primary color for glyph-on-surface use. */
.mds-dropdown-item__check-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
  block-size: var(--mds-icons-md);
  flex-shrink: 0;
}

.mds-dropdown-item__check {
  display: inline-block;
  flex-shrink: 0;
  inline-size: var(--mds-icons-xs);
  block-size: var(--mds-icons-xxs);
  background-color: var(--mds-text-link-primary-default);
  margin: auto 0;
  mask-image: url("data:image/svg+xml,%3Csvg%20width%3D%2210%22%20height%3D%227%22%20viewBox%3D%220%200%209.33333%207%22%20fill%3D%22none%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%20%3Cpath%20d%3D%22M2.72458%206.68529C3.13939%207.1049%203.78047%207.1049%204.19529%206.68529L9.02222%201.80245C9.43704%201.38283%209.43704%200.734332%209.02222%200.314714C8.60741%20-0.104905%207.96633%20-0.104905%207.55152%200.314714L3.47879%204.43461L1.78182%202.75613C1.367%202.33651%200.725926%202.33651%200.311111%202.75613C-0.103704%203.17575%20-0.103704%203.82425%200.311111%204.24387L2.72458%206.68529Z%22%20fill%3D%22%231D2125%22%2F%3E%20%3C%2Fsvg%3E");
  mask-repeat: no-repeat;
