  -webkit-mask-image: url("data:image/svg+xml,%3Csvg%20width%3D%2210%22%20height%3D%227%22%20viewBox%3D%220%200%209.33333%207%22%20fill%3D%22none%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%20%3Cpath%20d%3D%22M2.72458%206.68529C3.13939%207.1049%203.78047%207.1049%204.19529%206.68529L9.02222%201.80245C9.43704%201.38283%209.43704%200.734332%209.02222%200.314714C8.60741%20-0.104905%207.96633%20-0.104905%207.55152%200.314714L3.47879%204.43461L1.78182%202.75613C1.367%202.33651%200.725926%202.33651%200.311111%202.75613C-0.103704%203.17575%20-0.103704%203.82425%200.311111%204.24387L2.72458%206.68529Z%22%20fill%3D%22%231D2125%22%2F%3E%20%3C%2Fsvg%3E");
  -webkit-mask-repeat: no-repeat;
  -webkit-mask-position: center;
  -webkit-mask-size: contain;
}

/* Check is always in the DOM to preserve trailing-column width across
   selection state changes. Hide it visually when the row is unselected. */
.mds-dropdown-item--select:not(.mds-dropdown-item--selected) .mds-dropdown-item__check {
  visibility: hidden;
}

.mds-dropdown-item:disabled .mds-dropdown-item__check,
.mds-dropdown-item[aria-disabled=true] .mds-dropdown-item__check {
  background-color: var(--mds-text-muted);
}

/* ------------------------------------------------------------------ */
/* Expandable item                                                     */
/* ------------------------------------------------------------------ */
.mds-dropdown-item--expandable:hover:not(:disabled):not([aria-disabled=true]) {
  background-color: var(--mds-bg-interactive-primary-default-light);
}

.mds-dropdown-item--expandable:active:not(:disabled):not([aria-disabled=true]) {
  background-color: var(--mds-bg-interactive-primary-default-light);
}

.mds-dropdown-item__chevron-right {
  display: inline-block;
  flex-shrink: 0;
  inline-size: var(--mds-icons-xxs);
  block-size: var(--mds-icons-xs);
  background-color: var(--mds-text-subtle);
  mask-image: url("data:image/svg+xml,%3Csvg%20width%3D%227%22%20height%3D%2211%22%20viewBox%3D%220%200%206.01172%2010.5117%22%20fill%3D%22none%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%20%3Cpath%20d%3D%22M5.7832%204.72852C6.08789%205.00977%206.08789%205.50195%205.7832%205.7832L1.2832%2010.2832C1.00195%2010.5879%200.509766%2010.5879%200.228516%2010.2832C-0.0761719%2010.002%20-0.0761719%209.50977%200.228516%209.22852L4.18945%205.24414L0.228516%201.2832C-0.0761719%201.00195%20-0.0761719%200.509766%200.228516%200.228516C0.509766%20-0.0761719%201.00195%20-0.0761719%201.2832%200.228516L5.7832%204.72852Z%22%20fill%3D%22%231D2125%22%2F%3E%20%3C%2Fsvg%3E");
  mask-repeat: no-repeat;
  mask-position: center;
  mask-size: contain;
  -webkit-mask-image: url("data:image/svg+xml,%3Csvg%20width%3D%227%22%20height%3D%2211%22%20viewBox%3D%220%200%206.01172%2010.5117%22%20fill%3D%22none%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%20%3Cpath%20d%3D%22M5.7832%204.72852C6.08789%205.00977%206.08789%205.50195%205.7832%205.7832L1.2832%2010.2832C1.00195%2010.5879%200.509766%2010.5879%200.228516%2010.2832C-0.0761719%2010.002%20-0.0761719%209.50977%200.228516%209.22852L4.18945%205.24414L0.228516%201.2832C-0.0761719%201.00195%20-0.0761719%200.509766%200.228516%200.228516C0.509766%20-0.0761719%201.00195%20-0.0761719%201.2832%200.228516L5.7832%204.72852Z%22%20fill%3D%22%231D2125%22%2F%3E%20%3C%2Fsvg%3E");
