}

/* Mirror the submenu chevron under RTL so it keeps pointing towards the
   inline-end where the submenu opens. */
[dir=rtl] .mds-dropdown-item__chevron-right {
  transform: scaleX(-1);
}

/* Disabled expandable row: mute the chevron to match the label color. */
.mds-dropdown-item[aria-disabled=true] .mds-dropdown-item__chevron-right {
  background-color: var(--mds-text-muted);
}

/* ------------------------------------------------------------------ */
/* Header item                                                         */
/* ------------------------------------------------------------------ */
.mds-dropdown-item--header {
  cursor: default;
  gap: var(--mds-spacing-xxs);
}

.mds-dropdown-item--header .mds-dropdown-item__label {
  font-size: var(--mds-font-size-paragraph-small);
  font-weight: var(--mds-font-weight-medium);
  line-height: var(--mds-line-height-paragraph-xs);
  color: var(--mds-text-muted);
}

/* ------------------------------------------------------------------ */
/* Divider                                                             */
/* ------------------------------------------------------------------ */
.mds-dropdown-divider {
  inline-size: 100%;
  block-size: var(--mds-stroke-weight-sm);
  background-color: var(--mds-border-default);
  border-radius: var(--mds-border-radius-pill);
  flex-shrink: 0;
}

/* ------------------------------------------------------------------ */
/* List item                                                         */
/* ------------------------------------------------------------------ */
.mds-dropdown-item--list {
  pointer-events: none;
  align-items: flex-start;
}

/* List rows can contain longer status text; allow wrapping on narrow menus
   instead of inheriting the default single-line ellipsis behavior. */
.mds-dropdown-item--list .mds-dropdown-item__label {
  color: var(--mds-text-subtle);
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  overflow-wrap: anywhere;
}

/* Keep the list indicator aligned with the first text line when labels wrap. */
.mds-dropdown-item--list .mds-dropdown-item__check {
  /* margin-block-start: var(--mds-spacing-xxs); */
}

/* Unselected (todo) list items show an empty circle instead of the filled check. */
.mds-dropdown-item--list:not(.mds-dropdown-item--selected) .mds-dropdown-item__check {
  background-color: var(--mds-text-subtle);
  mask-image: url("data:image/svg+xml,%3Csvg%20width%3D%2212%22%20height%3D%2212%22%20viewBox%3D%220%200%2012%2012%22%20fill%3D%22none%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%20%3Cpath%20d%3D%22M6%2012C2.67188%2012%200%209.32812%200%206C0%202.69531%202.67188%200%206%200C9.30469%200%2012%202.69531%2012%206C12%209.32812%209.30469%2012%206%2012ZM6%201.125C3.28125%201.125%201.125%203.30469%201.125%206C1.125%208.71875%203.28125%2010.875%206%2010.875C8.69531%2010.875%2010.875%208.71875%2010.875%206C10.875%203.30469%208.69531%201.125%206%201.125Z%22%20fill%3D%22%23495057%22%2F%3E%20%3C%2Fsvg%3E");
  -webkit-mask-image: url("data:image/svg+xml,%3Csvg%20width%3D%2212%22%20height%3D%2212%22%20viewBox%3D%220%200%2012%2012%22%20fill%3D%22none%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%20%3Cpath%20d%3D%22M6%2012C2.67188%2012%200%209.32812%200%206C0%202.69531%202.67188%200%206%200C9.30469%200%2012%202.69531%2012%206C12%209.32812%209.30469%2012%206%2012ZM6%201.125C3.28125%201.125%201.125%203.30469%201.125%206C1.125%208.71875%203.28125%2010.875%206%2010.875C8.69531%2010.875%2010.875%208.71875%2010.875%206C10.875%203.30469%208.69531%201.125%206%201.125Z%22%20fill%3D%22%23495057%22%2F%3E%20%3C%2Fsvg%3E");
}

/* List items are aria-disabled for read-only semantics; keep done state check
   on the primary token instead of inheriting the generic disabled mute color. */
.mds-dropdown-item--list.mds-dropdown-item--selected .mds-dropdown-item__check {
  background-color: var(--mds-text-link-primary-default);
}

/* ------------------------------------------------------------------ */
/* Multiselect item                                                    */
/* ------------------------------------------------------------------ */
/* Keep top/bottom spacing on the XS token while preserving the default
   horizontal spacing used by other dropdown rows. */
.mds-dropdown-item.mds-dropdown-item--multiselect {
  padding-block: var(--mds-spacing-xs);
  gap: 0; /* Checkbox has its own internal gap. */
}

.mds-dropdown-item--multiselect:hover:not([aria-disabled=true]) {
  background-color: var(--mds-bg-interactive-primary-default-light);
}

.mds-dropdown-item--multiselect:active:not([aria-disabled=true]) {
  background-color: var(--mds-bg-interactive-primary-default-light);
}

/* Multiselect rows can include longer option labels; wrap rather than
   truncating so text does not collide with the trailing indicator area. */
.mds-dropdown-item--multiselect .mds-dropdown-item__label {
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  overflow-wrap: anywhere;
}

/* The inert wrapper span for the Checkbox visual indicator — remove from
   layout flow so the Checkbox's own form-check structure sits inline. */
.mds-dropdown-item__checkbox {
  display: contents;
}

/* ------------------------------------------------------------------ */
/* Custom item (slot)                                                  */
/* ------------------------------------------------------------------ */
.mds-dropdown-item--custom {
  cursor: default;
}

.mds-dropdown-item__slot {
  flex: 1 0 0;
  min-inline-size: 0;
}

/* ------------------------------------------------------------------ */
/* Group wrapper                                                       */
/* ------------------------------------------------------------------ */
/* display:contents removes the wrapper from layout flow so the menu
   panel's gap applies uniformly across group labels and items. */
.mds-dropdown-item-group {
  display: contents;
}

/* Styled to match DropdownItemHeader visually. */
.mds-dropdown-item-group__label {
  display: flex;
  align-items: center;
  inline-size: 100%;
  padding: var(--mds-spacing-xs) var(--mds-spacing-sm);
  font-size: var(--mds-font-size-paragraph-small);
  font-weight: var(--mds-font-weight-medium);
  color: var(--mds-text-muted);
  line-height: var(--mds-line-height-paragraph-xs);
  box-sizing: border-box;
  cursor: default;
}

/* ------------------------------------------------------------------ */
/* Composed Dropdown                                                   */
/* ------------------------------------------------------------------ */
.mds-dropdown {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  /* No position:relative needed — the menu is portaled via FloatingPortal */
}

/* favourite-button/index.css */
/* Favourite button (icon-only toggle) */
.mds-favourite-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: var(--mds-spacing-xs);
  border: none;
  border-radius: var(--mds-border-radius-pill);
  background-color: var(--mds-bg-surface-default);
  color: var(--mds-text-subtle);
  cursor: pointer;
  transition: background-color 0.15s ease-in-out, color 0.15s ease-in-out;
}

