  --cta-band: #570d82;
  --cta-button: #570d82;
  --cta-button-hover: #32064c;
  --cta-tick: #570d82;
}
[data-bs-theme=dark] .admin-notification-ctas .admin-notification-cta[data-cta-key=marketplace] {
  --cta-button: #a37aba;
  --cta-button-hover: #c4aad3;
